from collections import deque
from bisect import bisect_left

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.fw = [0]*(n+1)
    def update(self, i, v):
        while i <= self.n:
            self.fw[i] += v
            i += i & (-i)
    def query(self, i):
        s = 0
        while i > 0:
            s += self.fw[i]
            i -= i & (-i)
        return s

class Solution:
    def minInteger(self, num: str, k: int) -> str:
        n = len(num)
        pos = [[] for _ in range(10)]
        for i, ch in enumerate(num):
            pos[int(ch)].append(i+1)  # 1-based indexing for Fenwick tree

        # Fenwick tree to track how many characters have been moved out before a position
        fenw = FenwickTree(n)
        res = []

        # pointers to track which occurrence of each digit we have used
        idx = [0]*10

        for _ in range(n):
            for d in range(10):
                if idx[d] < len(pos[d]):
                    original_pos = pos[d][idx[d]]
                    # number of moved out chars before original_pos
                    moved_before = fenw.query(original_pos)
                    # effective position after removing moved chars before it
                    effective_pos = original_pos - moved_before
                    if effective_pos - 1 <= k:
                        k -= (effective_pos - 1)
                        fenw.update(original_pos, 1)
                        res.append(str(d))
                        idx[d] += 1
                        break
        return "".join(res)

